-- P0-1 MANUAL APPLY. DDL is intentionally outside the DML transaction because MySQL/MariaDB implicitly commits DDL.
DELIMITER //
DROP PROCEDURE IF EXISTS p01_guard_and_ddl//
CREATE PROCEDURE p01_guard_and_ddl()
BEGIN
 IF (SELECT COUNT(*) FROM organizational_units WHERE unit_code='PRES')>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: PRES root is ambiguous'; END IF;
 IF (SELECT COUNT(*) FROM roles WHERE role_code IN ('exam_officer','registration_officer','doctor_instructor','student') AND is_active=1)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: required P0-1 role missing'; END IF;
 IF (SELECT COUNT(*) FROM users WHERE username IN ('registrar','exam.board'))<>2 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: registrar and exam.board test users must exist before identity linking'; END IF;
 IF (SELECT COUNT(*) FROM permissions WHERE permission_code IN ('students.view','students.manage','admissions.view','admissions.manage','academic_structure.view','courses.view','registration.view','registration.manage','exams.view','exams.manage','grades.view','grades.manage','attendance.view','attendance.manage','system_settings.view') AND is_active=1)<>15 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: required P0-1 permission missing'; END IF;
 IF (SELECT COUNT(*) FROM organizational_unit_types WHERE type_code IN ('presidency','vice_presidency','administration','directorate','office','center','club','college','institute','lab','unit') AND is_active=1)<>11 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: required organizational type missing or ambiguous'; END IF;
 IF EXISTS(SELECT 1 FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND referenced_table_name='organizational_units' AND referenced_column_name='organizational_unit_id' AND table_name NOT IN ('boards','colleges','departments','employees','employee_positions','employee_unit_assignments','organizational_units')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: unknown organizational-unit foreign key requires a reviewed migration rule'; END IF;
 IF EXISTS(SELECT student_id FROM users WHERE student_id IS NOT NULL GROUP BY student_id HAVING COUNT(*)>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: duplicate student links'; END IF;
 IF EXISTS(SELECT employee_id FROM users WHERE employee_id IS NOT NULL GROUP BY employee_id HAVING COUNT(*)>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: duplicate employee links'; END IF;
 IF EXISTS(SELECT 1 FROM employees WHERE (email='registrar@rowad.edu' AND employee_number<>'P01-REGISTRAR') OR (email='exam.officer@rowad.edu' AND employee_number<>'P01-EXAM-OFFICER')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: deterministic staff email belongs to another employee'; END IF;
 IF EXISTS(SELECT 1 FROM users u LEFT JOIN employees e ON e.employee_id=u.employee_id WHERE (u.username='registrar' AND u.employee_id IS NOT NULL AND COALESCE(e.employee_number,'')<>'P01-REGISTRAR') OR (u.username='exam.board' AND u.employee_id IS NOT NULL AND COALESCE(e.employee_number,'')<>'P01-EXAM-OFFICER')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: operational test user is linked to an unexpected employee'; END IF;
 IF EXISTS(SELECT 1 FROM information_schema.statistics s WHERE s.table_schema=DATABASE() AND s.table_name='users' AND ((s.index_name='uq_users_student_identity' AND NOT(s.column_name='student_id' AND s.non_unique=0)) OR (s.index_name='uq_users_employee_identity' AND NOT(s.column_name='employee_id' AND s.non_unique=0)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: identity unique index name has incompatible definition'; END IF;
 IF EXISTS(SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='user_access_scopes') AND (NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='user_access_scopes' AND column_name='scope_id' AND data_type='int' AND column_type NOT LIKE '%unsigned%') OR NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='user_access_scopes' AND column_name='user_id' AND data_type='int' AND column_type NOT LIKE '%unsigned%') OR (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='user_access_scopes' AND column_name IN ('user_access_scope_id','user_id','scope_type','scope_id','is_active','created_at','updated_at'))<>7 OR NOT EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='user_access_scopes' AND index_name='user_scope_unique' AND non_unique=0) OR NOT EXISTS(SELECT 1 FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND table_name='user_access_scopes' AND column_name='user_id' AND referenced_table_name='users' AND referenced_column_name='user_id')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: incompatible user_access_scopes structure'; END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='users' AND index_name='uq_users_student_identity') THEN ALTER TABLE users ADD UNIQUE KEY uq_users_student_identity(student_id); END IF;
 IF NOT EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='users' AND index_name='uq_users_employee_identity') THEN ALTER TABLE users ADD UNIQUE KEY uq_users_employee_identity(employee_id); END IF;
END//
CALL p01_guard_and_ddl()//
DROP PROCEDURE p01_guard_and_ddl//
DELIMITER ;
CREATE TABLE IF NOT EXISTS user_access_scopes (user_access_scope_id BIGINT NOT NULL AUTO_INCREMENT,user_id INT NOT NULL,scope_type ENUM('university','college','department','program','section') NOT NULL,scope_id INT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NULL DEFAULT NULL,updated_at TIMESTAMP NULL DEFAULT NULL,PRIMARY KEY(user_access_scope_id),UNIQUE KEY user_scope_unique(user_id,scope_type,scope_id),KEY active_scope_lookup(scope_type,scope_id,is_active),CONSTRAINT fk_user_access_scopes_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- The table DDL above may commit implicitly. This second, standalone guard runs
-- before any business DML and deliberately stops for every unresolved scope.
DELIMITER //
DROP PROCEDURE IF EXISTS p01_guard_scope_data//
CREATE PROCEDURE p01_guard_scope_data()
BEGIN
 IF EXISTS(SELECT 1 FROM user_access_scopes s LEFT JOIN organizational_units root ON s.scope_type='university' AND root.organizational_unit_id=s.scope_id AND root.unit_code='PRES' LEFT JOIN organizational_units legacy_root ON s.scope_type='university' AND legacy_root.organizational_unit_id=s.scope_id AND legacy_root.unit_code IN ('VP_ADMIN','VP_SCI','VP_COMM') LEFT JOIN colleges c ON s.scope_type='college' AND c.college_id=s.scope_id LEFT JOIN departments d ON s.scope_type='department' AND d.department_id=s.scope_id LEFT JOIN academic_programs p ON s.scope_type='program' AND p.academic_program_id=s.scope_id LEFT JOIN course_offerings co ON s.scope_type='section' AND co.course_offering_id=s.scope_id WHERE CASE s.scope_type WHEN 'university' THEN COALESCE(root.organizational_unit_id,legacy_root.organizational_unit_id) WHEN 'college' THEN c.college_id WHEN 'department' THEN d.department_id WHEN 'program' THEN p.academic_program_id WHEN 'section' THEN co.course_offering_id ELSE NULL END IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: orphan or unsupported access scope requires manual resolution'; END IF;
 IF EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.user_id AND ur.is_active=1 JOIN roles r ON r.role_id=ur.role_id AND r.role_code IN ('registration_officer','exam_officer') WHERE u.username NOT IN ('registrar','exam.board') AND NOT EXISTS(SELECT 1 FROM user_access_scopes s LEFT JOIN organizational_units ou ON s.scope_type='university' AND ou.organizational_unit_id=s.scope_id LEFT JOIN colleges c ON s.scope_type='college' AND c.college_id=s.scope_id LEFT JOIN departments d ON s.scope_type='department' AND d.department_id=s.scope_id LEFT JOIN academic_programs p ON s.scope_type='program' AND p.academic_program_id=s.scope_id LEFT JOIN course_offerings co ON s.scope_type='section' AND co.course_offering_id=s.scope_id WHERE s.user_id=u.user_id AND s.is_active=1 AND CASE s.scope_type WHEN 'university' THEN IF(ou.unit_code IN ('PRES','VP_ADMIN','VP_SCI','VP_COMM'),ou.organizational_unit_id,NULL) WHEN 'college' THEN c.college_id WHEN 'department' THEN d.department_id WHEN 'program' THEN p.academic_program_id WHEN 'section' THEN co.course_offering_id ELSE NULL END IS NOT NULL)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: active operational user requires a manually reviewed valid scope'; END IF;
END//
CALL p01_guard_scope_data()//
DROP PROCEDURE p01_guard_scope_data//
DELIMITER ;
START TRANSACTION;
DROP TEMPORARY TABLE IF EXISTS p01_expected;
CREATE TEMPORARY TABLE p01_expected(role_code VARCHAR(80),permission_code VARCHAR(120),PRIMARY KEY(role_code,permission_code));
INSERT INTO p01_expected VALUES ('exam_officer','students.view'),('exam_officer','academic_structure.view'),('exam_officer','courses.view'),('exam_officer','registration.view'),('exam_officer','exams.view'),('exam_officer','exams.manage'),('exam_officer','grades.view'),('exam_officer','grades.manage'),('exam_officer','system_settings.view'),('registration_officer','students.view'),('registration_officer','students.manage'),('registration_officer','admissions.view'),('registration_officer','admissions.manage'),('registration_officer','academic_structure.view'),('registration_officer','courses.view'),('registration_officer','registration.view'),('registration_officer','registration.manage'),('registration_officer','system_settings.view'),('doctor_instructor','courses.view'),('doctor_instructor','students.view'),('doctor_instructor','attendance.view'),('doctor_instructor','attendance.manage'),('doctor_instructor','grades.view'),('doctor_instructor','grades.manage'),('student','students.view'),('student','registration.view'),('student','grades.view'),('student','attendance.view');
INSERT INTO role_permissions(role_id,permission_id,granted_at) SELECT r.role_id,p.permission_id,CURRENT_TIMESTAMP FROM p01_expected x JOIN roles r USING(role_code) JOIN permissions p USING(permission_code) LEFT JOIN role_permissions rp ON rp.role_id=r.role_id AND rp.permission_id=p.permission_id WHERE rp.role_permission_id IS NULL;
-- Seed/correct only the 58 authoritative official codes; unrelated units are untouched.
INSERT INTO organizational_units(unit_code,unit_name,unit_type_id,parent_unit_id,description,is_active,created_at,updated_at) SELECT 'PRES','رئيس الجامعة',t.unit_type_id,NULL,'Official organizational chart',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM organizational_unit_types t WHERE t.type_code='presidency' ON DUPLICATE KEY UPDATE unit_name=VALUES(unit_name),unit_type_id=VALUES(unit_type_id),parent_unit_id=NULL,is_active=1,updated_at=CURRENT_TIMESTAMP;
INSERT INTO organizational_units(unit_code,unit_name,unit_type_id,parent_unit_id,description,is_active,created_at,updated_at) SELECT x.code,x.name,t.unit_type_id,p.organizational_unit_id,'Official organizational chart',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM (SELECT '1' code,'إدارة البحوث والدراسات' name,'administration' type_code,'PRES' parent_code UNION ALL SELECT '2','إدارة التطوير ودعم القرار','administration','PRES' UNION ALL SELECT '3','إدارة التعليم الإلكتروني','administration','PRES' UNION ALL SELECT '4','الأمين العام للجامعة','administration','PRES' UNION ALL SELECT '5','مديرية العلاقات العامة والإعلام','directorate','PRES' UNION ALL SELECT '6','وحدة التقييم والمتابعة','unit','PRES' UNION ALL SELECT '7','نائب رئيس الجامعة للشؤون الإدارية','vice_presidency','PRES' UNION ALL SELECT '8','نائب رئيس الجامعة للشؤون العلمية','vice_presidency','PRES' UNION ALL SELECT '9','نائب رئيس الجامعة للشؤون المجتمعية','vice_presidency','PRES') x JOIN organizational_unit_types t ON t.type_code=x.type_code JOIN organizational_units p ON p.unit_code=x.parent_code ON DUPLICATE KEY UPDATE unit_name=VALUES(unit_name),unit_type_id=VALUES(unit_type_id),parent_unit_id=VALUES(parent_unit_id),is_active=1,updated_at=CURRENT_TIMESTAMP;
INSERT INTO organizational_units(unit_code,unit_name,unit_type_id,parent_unit_id,description,is_active,created_at,updated_at) SELECT x.code,x.name,t.unit_type_id,p.organizational_unit_id,'Official organizational chart',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM (SELECT '11' code,'مركز البحوث والدراسات' name,'center' type_code,'1' parent_code UNION ALL SELECT '12','مجلة جامعة الرواد','unit','1' UNION ALL SELECT '13','المكتبة','unit','1' UNION ALL SELECT '21','وحدة نظم المعلومات والتخطيط الاستراتيجي','unit','2' UNION ALL SELECT '22','الجودة والاعتماد الأكاديمي','unit','2' UNION ALL SELECT '23','مشاريع إنتاجية','unit','2' UNION ALL SELECT '31','التعليم عن بعد','unit','3' UNION ALL SELECT '32','التعليم الافتراضي','unit','3' UNION ALL SELECT '41','مكتب الشؤون القانونية','office','4' UNION ALL SELECT '42','مكتب الأمن والسلامة','office','4' UNION ALL SELECT '51','مكتب العلاقات العامة','office','5' UNION ALL SELECT '52','مكتب الإعلام والاتصال','office','5' UNION ALL SELECT '71','مديرية الشؤون الإدارية','directorate','7' UNION ALL SELECT '72','مديرية الشؤون المالية','directorate','7' UNION ALL SELECT '73','مديرية شؤون الطلاب','directorate','7' UNION ALL SELECT '81','إدارة التعليم الجامعي','administration','8' UNION ALL SELECT '82','إدارة الدراسات العليا والبحث العلمي','administration','8' UNION ALL SELECT '91','إدارة تنمية وبناء القدرات','administration','9' UNION ALL SELECT '92','إدارة الأنشطة المجتمعية','administration','9') x JOIN organizational_unit_types t ON t.type_code=x.type_code JOIN organizational_units p ON p.unit_code=x.parent_code ON DUPLICATE KEY UPDATE unit_name=VALUES(unit_name),unit_type_id=VALUES(unit_type_id),parent_unit_id=VALUES(parent_unit_id),is_active=1,updated_at=CURRENT_TIMESTAMP;
INSERT INTO organizational_units(unit_code,unit_name,unit_type_id,parent_unit_id,description,is_active,created_at,updated_at) SELECT x.code,x.name,t.unit_type_id,p.organizational_unit_id,'Official organizational chart',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM (SELECT '711' code,'مكتب الموارد البشرية' name,'office' type_code,'71' parent_code UNION ALL SELECT '712','مكتب الديوان والأرشيف','office','71' UNION ALL SELECT '713','مكتب الرعاية الصحية','office','71' UNION ALL SELECT '714','مكتب الخدمات الإدارية','office','71' UNION ALL SELECT '715','المكتب التقني','office','71' UNION ALL SELECT '721','مكتب المحاسبة','office','72' UNION ALL SELECT '722','أمين الصندوق','office','72' UNION ALL SELECT '723','أمين المستودع','office','72' UNION ALL SELECT '731','مكتب الإرشاد والتوجيه','office','73' UNION ALL SELECT '732','مكتب القبول والتسجيل','office','73' UNION ALL SELECT '733','مكتب الخدمات الطلابية','office','73' UNION ALL SELECT '734','مكتب المنح والإيفاد والتبادل الطلابي','office','73' UNION ALL SELECT '735','إدارة الامتحانات','administration','73' UNION ALL SELECT '736','مكتب التوثيق والتصديق','office','73' UNION ALL SELECT '811','الكليات','college','81' UNION ALL SELECT '812','المعاهد','institute','81' UNION ALL SELECT '813','المخابر','lab','81' UNION ALL SELECT '821','الماجستير','unit','82' UNION ALL SELECT '822','الدكتوراه','unit','82' UNION ALL SELECT '823','التعليم المهني','unit','82' UNION ALL SELECT '911','مركز التأهيل والتدريب','center','91' UNION ALL SELECT '912','مركز اللغات الأجنبية','center','91' UNION ALL SELECT '913','مركز تقانة المعلومات','center','91' UNION ALL SELECT '914','مركز ريادة الأعمال','center','91' UNION ALL SELECT '921','نادي الشباب والرياضة','club','92' UNION ALL SELECT '922','نادي التطوع والأنشطة المجتمعية','club','92' UNION ALL SELECT '923','نادي أصدقاء البيئة','club','92' UNION ALL SELECT '924','مكتب المسؤولية المجتمعية','office','92' UNION ALL SELECT '925','مكتب العدالة وحقوق الإنسان','office','92') x JOIN organizational_unit_types t ON t.type_code=x.type_code JOIN organizational_units p ON p.unit_code=x.parent_code ON DUPLICATE KEY UPDATE unit_name=VALUES(unit_name),unit_type_id=VALUES(unit_type_id),parent_unit_id=VALUES(parent_unit_id),is_active=1,updated_at=CURRENT_TIMESTAMP;
-- Reconcile only confirmed legacy semantic aliases after all official replacements exist.
DROP TEMPORARY TABLE IF EXISTS p01_legacy_unit_map;
CREATE TEMPORARY TABLE p01_legacy_unit_map(legacy_code VARCHAR(50) PRIMARY KEY,official_code VARCHAR(50) NOT NULL);
INSERT INTO p01_legacy_unit_map VALUES ('VP_ADMIN','7'),('VP_SCI','8'),('VP_COMM','9'),('HR_OFFICE','711'),('LIBRARY','13'),('REG_OFFICE','732'),('EXAM_OFFICE','735');
-- Normalize confirmed legacy university grants to PRES while preserving every user's
-- effective grant and active state. Only redundant alias rows are removed.
DROP TEMPORARY TABLE IF EXISTS p01_legacy_scope_migration;
CREATE TEMPORARY TABLE p01_legacy_scope_migration(user_id INT PRIMARY KEY,was_active TINYINT(1),legacy_scope_count INT);
INSERT INTO p01_legacy_scope_migration SELECT s.user_id,MAX(s.is_active),COUNT(*) FROM user_access_scopes s JOIN organizational_units legacy ON legacy.organizational_unit_id=s.scope_id AND legacy.unit_code IN ('VP_ADMIN','VP_SCI','VP_COMM') WHERE s.scope_type='university' GROUP BY s.user_id;
INSERT INTO user_access_scopes(user_id,scope_type,scope_id,is_active,created_at,updated_at) SELECT m.user_id,'university',root.organizational_unit_id,m.was_active,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM p01_legacy_scope_migration m JOIN organizational_units root ON root.unit_code='PRES' ON DUPLICATE KEY UPDATE is_active=GREATEST(is_active,VALUES(is_active)),updated_at=CURRENT_TIMESTAMP;
DELETE s FROM user_access_scopes s JOIN organizational_units legacy ON legacy.organizational_unit_id=s.scope_id AND legacy.unit_code IN ('VP_ADMIN','VP_SCI','VP_COMM') WHERE s.scope_type='university';
SET @p01_scope_migration_guard=IF(EXISTS(SELECT 1 FROM p01_legacy_scope_migration m JOIN organizational_units root ON root.unit_code='PRES' LEFT JOIN user_access_scopes s ON s.user_id=m.user_id AND s.scope_type='university' AND s.scope_id=root.organizational_unit_id WHERE s.user_access_scope_id IS NULL),'SELECT * FROM p01_STOP_LEGACY_SCOPE_MIGRATION_LOST_GRANT','SELECT 1');
PREPARE stmt FROM @p01_scope_migration_guard; EXECUTE stmt; DEALLOCATE PREPARE stmt;
UPDATE employees x JOIN organizational_units legacy ON legacy.organizational_unit_id=x.organizational_unit_id JOIN p01_legacy_unit_map m ON m.legacy_code=legacy.unit_code JOIN organizational_units official ON official.unit_code=m.official_code SET x.organizational_unit_id=official.organizational_unit_id;
UPDATE employee_positions x JOIN organizational_units legacy ON legacy.organizational_unit_id=x.organizational_unit_id JOIN p01_legacy_unit_map m ON m.legacy_code=legacy.unit_code JOIN organizational_units official ON official.unit_code=m.official_code SET x.organizational_unit_id=official.organizational_unit_id;
UPDATE employee_unit_assignments x JOIN organizational_units legacy ON legacy.organizational_unit_id=x.organizational_unit_id JOIN p01_legacy_unit_map m ON m.legacy_code=legacy.unit_code JOIN organizational_units official ON official.unit_code=m.official_code SET x.organizational_unit_id=official.organizational_unit_id;
UPDATE boards x JOIN organizational_units legacy ON legacy.organizational_unit_id=x.organizational_unit_id JOIN p01_legacy_unit_map m ON m.legacy_code=legacy.unit_code JOIN organizational_units official ON official.unit_code=m.official_code SET x.organizational_unit_id=official.organizational_unit_id;
UPDATE colleges x JOIN organizational_units legacy ON legacy.organizational_unit_id=x.organizational_unit_id JOIN p01_legacy_unit_map m ON m.legacy_code=legacy.unit_code JOIN organizational_units official ON official.unit_code=m.official_code SET x.organizational_unit_id=official.organizational_unit_id;
UPDATE departments x JOIN organizational_units legacy ON legacy.organizational_unit_id=x.organizational_unit_id JOIN p01_legacy_unit_map m ON m.legacy_code=legacy.unit_code JOIN organizational_units official ON official.unit_code=m.official_code SET x.organizational_unit_id=official.organizational_unit_id;
UPDATE organizational_units child JOIN organizational_units legacy ON legacy.organizational_unit_id=child.parent_unit_id JOIN p01_legacy_unit_map m ON m.legacy_code=legacy.unit_code JOIN organizational_units official ON official.unit_code=m.official_code SET child.parent_unit_id=official.organizational_unit_id;
-- Materialize post-migration reference state before updating organizational_units.
-- This avoids MySQL error 1093 and deliberately reads this staging table only once per statement.
DROP TEMPORARY TABLE IF EXISTS p01_legacy_reference_state;
CREATE TEMPORARY TABLE p01_legacy_reference_state(legacy_id INT PRIMARY KEY,legacy_code VARCHAR(50),official_code VARCHAR(50),remaining_children INT,remaining_employees INT,remaining_positions INT,remaining_assignments INT,remaining_boards INT,remaining_colleges INT,remaining_departments INT,remaining_scopes INT);
INSERT INTO p01_legacy_reference_state
SELECT legacy.organizational_unit_id,legacy.unit_code,m.official_code,
 (SELECT COUNT(*) FROM organizational_units child WHERE child.parent_unit_id=legacy.organizational_unit_id),
 (SELECT COUNT(*) FROM employees x WHERE x.organizational_unit_id=legacy.organizational_unit_id),
 (SELECT COUNT(*) FROM employee_positions x WHERE x.organizational_unit_id=legacy.organizational_unit_id),
 (SELECT COUNT(*) FROM employee_unit_assignments x WHERE x.organizational_unit_id=legacy.organizational_unit_id),
 (SELECT COUNT(*) FROM boards x WHERE x.organizational_unit_id=legacy.organizational_unit_id),
 (SELECT COUNT(*) FROM colleges x WHERE x.organizational_unit_id=legacy.organizational_unit_id),
 (SELECT COUNT(*) FROM departments x WHERE x.organizational_unit_id=legacy.organizational_unit_id),
 (SELECT COUNT(*) FROM user_access_scopes x WHERE x.scope_type='university' AND x.scope_id=legacy.organizational_unit_id)
FROM p01_legacy_unit_map m JOIN organizational_units legacy ON legacy.unit_code=m.legacy_code;
SET @p01_legacy_guard_sql=IF(EXISTS(SELECT 1 FROM p01_legacy_reference_state WHERE remaining_children+remaining_employees+remaining_positions+remaining_assignments+remaining_boards+remaining_colleges+remaining_departments+remaining_scopes>0),'SELECT * FROM p01_STOP_LEGACY_UNIT_STILL_REFERENCED','SELECT 1');
PREPARE stmt FROM @p01_legacy_guard_sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
UPDATE organizational_units legacy JOIN p01_legacy_reference_state eligible ON eligible.legacy_id=legacy.organizational_unit_id SET legacy.is_active=0,legacy.description=CASE WHEN legacy.description LIKE CONCAT('%Superseded by official unit ',eligible.official_code,'%') THEN legacy.description ELSE CONCAT_WS(' ',legacy.description,CONCAT('Superseded by official unit ',eligible.official_code)) END;
-- Deterministic P0-1 test staff records and identity links. The users must already
-- exist with the documented test usernames; no password is created or reset here.
INSERT INTO employees(employee_number,first_name,last_name,email,hire_date,employee_type_id,employee_status_id,organizational_unit_id,created_at,updated_at)
SELECT 'P01-REGISTRAR','Test','Registrar','registrar@rowad.edu',CURRENT_DATE,et.employee_type_id,es.employee_status_id,ou.organizational_unit_id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM employee_types et JOIN employee_statuses es ON es.status_code='active' JOIN organizational_units ou ON ou.unit_code='732' WHERE et.type_code='administrative'
ON DUPLICATE KEY UPDATE first_name=VALUES(first_name),last_name=VALUES(last_name),email=VALUES(email),employee_type_id=VALUES(employee_type_id),employee_status_id=VALUES(employee_status_id),organizational_unit_id=VALUES(organizational_unit_id),updated_at=CURRENT_TIMESTAMP;
INSERT INTO employees(employee_number,first_name,last_name,email,hire_date,employee_type_id,employee_status_id,organizational_unit_id,created_at,updated_at)
SELECT 'P01-EXAM-OFFICER','Test','Exam Officer','exam.officer@rowad.edu',CURRENT_DATE,et.employee_type_id,es.employee_status_id,ou.organizational_unit_id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM employee_types et JOIN employee_statuses es ON es.status_code='active' JOIN organizational_units ou ON ou.unit_code='735' WHERE et.type_code='administrative'
ON DUPLICATE KEY UPDATE first_name=VALUES(first_name),last_name=VALUES(last_name),email=VALUES(email),employee_type_id=VALUES(employee_type_id),employee_status_id=VALUES(employee_status_id),organizational_unit_id=VALUES(organizational_unit_id),updated_at=CURRENT_TIMESTAMP;
UPDATE users u JOIN employees e ON e.employee_number='P01-REGISTRAR' SET u.employee_id=e.employee_id WHERE u.username='registrar' AND (u.employee_id IS NULL OR u.employee_id=e.employee_id);
UPDATE users u JOIN employees e ON e.employee_number='P01-EXAM-OFFICER' SET u.employee_id=e.employee_id WHERE u.username='exam.board' AND (u.employee_id IS NULL OR u.employee_id=e.employee_id);
INSERT INTO user_roles(user_id,role_id,assigned_by_user_id,assigned_at,is_active) SELECT u.user_id,r.role_id,NULL,CURRENT_TIMESTAMP,1 FROM users u JOIN roles r ON r.role_code=CASE u.username WHEN 'registrar' THEN 'registration_officer' WHEN 'exam.board' THEN 'exam_officer' END LEFT JOIN user_roles ur ON ur.user_id=u.user_id AND ur.role_id=r.role_id WHERE u.username IN ('registrar','exam.board') AND ur.user_role_id IS NULL;
UPDATE user_roles ur JOIN users u ON u.user_id=ur.user_id JOIN roles r ON r.role_id=ur.role_id SET ur.is_active=1 WHERE (u.username='registrar' AND r.role_code='registration_officer') OR (u.username='exam.board' AND r.role_code='exam_officer');
INSERT INTO user_access_scopes(user_id,scope_type,scope_id,is_active,created_at,updated_at) SELECT u.user_id,'university',root.organizational_unit_id,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM users u JOIN organizational_units root ON root.unit_code='PRES' WHERE u.username IN ('registrar','exam.board') AND u.employee_id IS NOT NULL ON DUPLICATE KEY UPDATE is_active=1,updated_at=CURRENT_TIMESTAMP;
COMMIT;
